@Component
class AuditService {

    private final RequestContext ctx;   // RequestContext is request-scoped
    private int handled;

    AuditService(RequestContext ctx) { this.ctx = ctx; }

    String audit() {
        handled++;
        return ctx.traceId();
    }
}

